'use strict';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>Number(x).toLocaleString('ar-SA');
let data,view='practice',section='الكل',category='الكل',difficulty='الكل',pool=[],question,selected=null,checked=false,session=0,history=[],exam=null,timer=null,large=false;
function title(t,s){return `<div class="topline"><div><p class="eyebrow">مساحتك لتطوير المهارات</p><h1>${t}</h1><p class="sub">${s}</p></div><span class="date-label">${new Date().toLocaleDateString('ar-SA',{day:'numeric',month:'long'})}</span></div>`}
function stats(){const correct=history.filter(h=>h.correct).length;return `<div class="stats"><div class="stat"><span>أسئلة متاحة للتدريب</span><strong>${num(data.questions.length)}</strong></div><div class="stat"><span>إجاباتك المسجّلة</span><strong>${num(history.length)}</strong></div><div class="stat"><span>دقة إجاباتك</span><strong>${history.length?num(Math.round(correct/history.length*100))+'٪':'—'}</strong></div></div>`}
function activate(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v))}
function go(v){if(exam&&v!=='exams'){touchExam();save();}activate(v);render()}
function render(){if(view==='practice')practice();if(view==='exams')exam?renderExam():exams();if(view==='progress')progress();if(view==='references')references();if(view==='manage')manage();if(view==='reports')reports()}
function choices(values,current){return values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('')}
function pick(){pool=data.questions.filter(q=>(section==='الكل'||q.section===section)&&(category==='الكل'||q.category===category)&&(difficulty==='الكل'||q.difficulty===difficulty));const candidates=pool.filter(q=>q.id!==question?.id);question=(candidates.length?candidates:pool)[Math.floor(Math.random()*(candidates.length||pool.length))];selected=null;checked=false}
function qMarkup(q,answer,reviewed){return `<div class="qmeta"><span>${esc(q.category)} <span class="tag">${esc(q.difficulty)}</span>${Number.isInteger(q.review?.batch)?'<span class="tag">مراجع تحريريًا</span>':''}</span><span dir="ltr">${esc(q.id)}</span></div><h2 class="qtext">${esc(q.text)}</h2><div class="options">${q.options.map((o,i)=>`<button class="option ${answer===i?'selected':''} ${reviewed?(i===q.answer?'correct':answer===i?'wrong':''):''}" data-answer="${i}" aria-pressed="${answer===i}" ${reviewed?'disabled':''}><span class="letter">${'أبجد'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div>`}
function practice(){if(!question)pick();const cats=['الكل',...new Set(data.questions.filter(q=>section==='الكل'||q.section===section).map(q=>q.category))];$('#main').innerHTML=title('كل سؤال، خطوة للأمام','اختر مهارتك، جرّب الحل، وتعلّم من الإجابة.')+stats()+`<div class="workspace"><section class="card"><div class="filters"><label>القسم<select id="section">${choices(['الكل','لفظي','كمي'],section)}</select></label><label>المهارة<select id="category">${choices(cats,category)}</select></label><label>الصعوبة<select id="difficulty">${choices(['الكل','سهل','متوسط','صعب'],difficulty)}</select></label></div>${question?qMarkup(question,selected,checked):'<div class="empty">لا توجد أسئلة بهذه الخيارات. غيّر أحد المرشّحات.</div>'}${checked?`<div class="feedback ${selected!==question.answer?'bad':''}" role="status"><b>${selected===question.answer?'أحسنت، إجابة صحيحة!':'لنراجع طريقة الحل'} — الإجابة: ${'أبجد'[question.answer]}</b><p>${esc(question.explanation)}</p></div>`:''}<div class="actions"><span class="muted">${num(pool.length)} سؤالًا ضمن اختيارك</span>${question?`<button class="primary" id="check" ${selected===null&&!checked?'disabled':''}>${checked?'السؤال التالي ←':'تحقّق من الإجابة'}</button>`:''}</div></section><div class="right-rail"><div class="side-card"><small>جلسة التدريب الحالية</small><div class="big">${num(session)}</div><h3>سؤالًا أنجزت</h3><hr><h3>الفهم قبل السرعة</h3><p>خذ وقتك في التفكير. في وضع التدريب، يظهر شرح الحل بعد تأكيد إجابتك.</p><small>بدون مؤقّت • تدريب على راحتك</small></div><div class="tip"><b>هل أنت جاهز للتحدّي؟</b><p>اختبر نفسك في ٦٠ سؤالًا، ثم راجع إجاباتك بالتفصيل.</p><button id="to-exams">عرض الاختبارات</button></div></div></div>`;for(const k of ['section','category','difficulty'])$('#'+k).onchange=e=>{if(k==='section'){section=e.target.value;category='الكل'}if(k==='category')category=e.target.value;if(k==='difficulty')difficulty=e.target.value;pick();practice()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{selected=+b.dataset.answer;practice()});if($('#check'))$('#check').onclick=()=>{if(checked){pick();practice()}else if(selected!==null){record(question,selected);session++;checked=true;practice()}};$('#to-exams')?.addEventListener('click',()=>go('exams'))}
function progress(){const groups=Object.create(null);history.forEach(h=>{const g=groups[h.category]??={n:0,c:0};g.n++;g.c+=h.correct?1:0});const rows=Object.entries(groups).sort((a,b)=>a[1].c/a[1].n-b[1].c/b[1].n);$('#main').innerHTML=title('تقدّمك، سؤالًا بسؤال','نتائج محاولاتك في هذا المتصفح. ابدأ بالمهارات التي تحتاج مراجعة.')+stats()+(rows.length?`<div class="grid">${rows.map(([name,g])=>`<section class="card"><h2>${esc(name)}</h2><p>${num(g.c)} صحيحة من ${num(g.n)} محاولة · ${num(Math.round(g.c/g.n*100))}٪</p><div class="progress-track"><span style="width:${g.c/g.n*100}%"></span></div><button data-train="${esc(name)}">تدرّب على هذه المهارة</button></section>`).join('')}</div>`:`<section class="card empty"><h2>أول إجابة هي البداية</h2><p>أكمل سؤالًا في التدريب لتظهر نتائجك هنا.</p><button id="begin" class="primary">ابدأ التدريب</button></section>`);document.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>{section='الكل';difficulty='الكل';category=b.dataset.train;pick();go('practice')});$('#begin')?.addEventListener('click',()=>go('practice'))}
function references(){$('#main').innerHTML=title('مصادر البنك','من أين جاءت الأسئلة، وما حدود استخدامها.')+`<section class="card" style="margin-bottom:20px"><h2>بنك الأسئلة الذكي · الإصدار ١٠</h2><p class="muted">تم استيراد ١٠٠٠ سؤال من ورقة بنك_الأسئلة_1000، و٥ اختبارات من مفاتيح_الاختبارات، ثم أُضيف ٤٩٠ سؤالًا جديدًا متوسطًا وصعبًا (الدفعة العاشرة) بعد حلها حلًا مستقلًا والتأكد من تطابق المفتاح. رُوجع أول ${num(window.GAT_BASE.editorialReview?.reviewedCount||0)} سؤال مراجعة تحريرية؛ بقي ${num(window.GAT_BASE.editorialReview?.remainingCount??1000)} سؤال خارج الدفعات المكتملة. المحاكاة تدريبية وليست معتمدة رسميًا.</p><p class="muted">استُخرجت الأسئلة والمفاتيح من الملفات المرجعية ثم رُوجعت تحريريًا، ولم تُرفَق تلك الملفات مع المنصة. لا يُعد أي مصدر توثيقًا لاختبار رسمي ولا ضمانًا لتكرار الأسئلة.</p></section><div class="grid">${(data.references||[]).map(r=>`<section class="card ref"><span class="tag">PDF · ${num(r.pages)} صفحة</span><h2 dir="auto">${esc(r.name)}</h2><a href="${esc(r.url)}" target="_blank" rel="noopener">فتح المرجع ↗</a></section>`).join('')}</div>`}
